document?

SELECT ?agent
WHERE {
  ?document a aml:Document ;
            aml:hasAuditTrail ?auditTrail .
  ?auditTrail aml:hasAuditTrailEntry ?entry .
  ?entry aml:requiresRole ?role .
  ?role <http://www.ontologydesignpatterns.org/cp/owl/bag.owl#isRoleOf> ?agent .
  FILTER(?document = <SPECIFIC_DOCUMENT_URI>)
}

